using System.Diagnostics;
using System.Net;
using System.Text;
using System.Text.Json;
using FluentAssertions;
using Microsoft.Data.SqlClient;
using Testcontainers.MsSql;
using Xrmd.Cli;
using Xrmd.Cli.Auth;
using Xrmd.Abstractions.Sdk;
using Xrmd.TestSupport;
using Xunit.Abstractions;

namespace Xrmd.Integration.Tests;

/// <summary>
/// Plan 10, ruling P5: a new installation runs the SQL Server Express edition, and xrmd works on it. As in
/// <see cref="MultiOrgAcceptanceTests"/>, the installation is generated by the real <c>xrmd server init</c> and resolved by
/// the real <c>docker compose config</c>; the <c>sqlserver</c> service is a Testcontainers SQL Server started with that
/// service's <c>MSSQL_PID</c> and <c>SA_PASSWORD</c>, and <c>xrmd-&lt;org&gt;</c> runs as an <c>Xrmd.Host</c> process
/// with the service's resolved environment (only <c>Server=</c>, the listening URL and the files root differ).
/// </summary>
[Trait("Category", "Acceptance")]
public sealed class SqlEditionAcceptanceTests(ITestOutputHelper output) : IAsyncLifetime
{
    private const int Port = 5071;

    private readonly string _root = Path.Combine(Path.GetTempPath(), "xrmd-sqledition-acceptance", Guid.NewGuid().ToString("N"));
    private readonly HttpClient _http = new() { Timeout = TimeSpan.FromSeconds(30) };
    private readonly StringBuilder _hostOutput = new();
    private MsSqlContainer? _sql;
    private Process? _host;

    private string InstallDir => Path.Combine(_root, "install");

    private string _hostFolder = "";
    private string _sdk = "";

    /// <summary>The published host (no Microsoft SDK in it, its own deps.json) and an SDK folder installed from the cached package (Plan 12).</summary>
    public async Task InitializeAsync()
    {
        _hostFolder = await PublishedApps.HostAsync();
        _sdk = await PublishedApps.InstalledSdkAsync();
    }

    public async Task DisposeAsync()
    {
        if (_host is not null)
        {
            try
            {
                if (!_host.HasExited)
                {
                    _host.Kill(entireProcessTree: true);
                    _host.WaitForExit(10_000);
                }
            }
            catch (InvalidOperationException) { }
            _host.Dispose();
        }
        _http.Dispose();
        if (_sql is not null) await _sql.DisposeAsync();
        try { Directory.Delete(_root, recursive: true); } catch (DirectoryNotFoundException) { }
        PublishedApps.DeleteFolder(_sdk);
    }

    [Fact]
    public async Task Express_edition_runs_migrations_and_seed()
    {
        // 1. `server init` without --sql-edition: MSSQL_PID=Express, required by the sqlserver service.
        string? signingKey = null;
        var stdout = new StringWriter();
        var err = new StringWriter();
        var env = new CliEnvironment(stdout, err, new StringReader(""), false, null, Path.Combine(_root, "config"), new NoDocker(), TimeProvider.System)
        {
            GetEnvironmentVariable = name => name == DevTokenProvider.DefaultSigningKeyEnv ? signingKey : null,
        };
        (await CliApp.RunAsync(["server", "init", "--accept-sql-server-eula", "--dir", InstallDir, "--org", "acme", "--port", Port.ToString(System.Globalization.CultureInfo.InvariantCulture)], env)).Should().Be(0, err.ToString());
        err.ToString().Should().NotContain("Developer", "no Developer edition warning for a new installation (the only output is the hint to install the SDK)");
        var services = await ResolvedServicesAsync();
        var sqlEnvironment = services["sqlserver"].GetProperty("environment");
        var edition = sqlEnvironment.GetProperty("MSSQL_PID").GetString();
        edition.Should().Be("Express");

        // 2. The sqlserver service, emulated: the same image, with the service's MSSQL_PID and sa password.
        _sql = new MsSqlBuilder("mcr.microsoft.com/mssql/server:2022-latest")
            .WithPassword(sqlEnvironment.GetProperty("MSSQL_SA_PASSWORD").GetString()!.Replace("$$", "$"))
            .WithEnvironment("MSSQL_PID", edition)
            .Build();
        await _sql.StartAsync();
        (await ScalarAsync("master", "SELECT CAST(SERVERPROPERTY('Edition') AS nvarchar(128))")).Should().Contain("Express");

        // 3. xrmd-acme on it: startup creates the database, migrates and seeds, then answers /healthz.
        StartHost(services["xrmd-acme"]);
        await WaitHealthyAsync();
        (await ScalarAsync("acme", "SELECT COUNT(*) FROM sys.tables")).Should().NotBe("0", "the migrations created the tables");
        (await ScalarAsync("acme", "SELECT DB_NAME()")).Should().Be("acme");

        // 4. The seed: WhoAmI as the generated administrator, through the dev profile `server init` created.
        signingKey = ReadEnv()["AUTH_DEV_SIGNING_KEY"];
        stdout.GetStringBuilder().Clear();
        (await CliApp.RunAsync(["auth", "status", "--profile", "acme", "-o", "json"], env)).Should().Be(0, err + "\n" + HostOutput);
        using var whoAmI = JsonDocument.Parse(stdout.ToString());
        var json = whoAmI.RootElement.ValueKind == JsonValueKind.Array ? whoAmI.RootElement[0] : whoAmI.RootElement;
        json.GetProperty("organizationId").GetString().Should().NotBeNullOrEmpty();
    }

    private string HostOutput
    {
        get { lock (_hostOutput) return _hostOutput.ToString(); }
    }

    private Dictionary<string, string> ReadEnv() =>
        File.ReadAllLines(Path.Combine(InstallDir, ".env"))
            .Where(l => l.Length > 0 && !l.StartsWith('#'))
            .Select(l => l.Split('=', 2))
            .ToDictionary(p => p[0], p => p[1]);

    private async Task<string?> ScalarAsync(string database, string sql)
    {
        await using var conn = new SqlConnection(new SqlConnectionStringBuilder(_sql!.GetConnectionString()) { InitialCatalog = database }.ConnectionString);
        await conn.OpenAsync();
        await using var cmd = new SqlCommand(sql, conn);
        return (await cmd.ExecuteScalarAsync())?.ToString();
    }

    /// <summary>The services of <c>docker compose config --format json</c> of the installation (the real Compose, with interpolation).</summary>
    private async Task<Dictionary<string, JsonElement>> ResolvedServicesAsync()
    {
        var start = new ProcessStartInfo("docker") { RedirectStandardOutput = true, RedirectStandardError = true, WorkingDirectory = InstallDir };
        foreach (var arg in new[] { "compose", "-f", Path.Combine(InstallDir, "docker-compose.yml"), "--env-file", Path.Combine(InstallDir, ".env"), "config", "--format", "json" })
            start.ArgumentList.Add(arg);
        using var process = Process.Start(start)!;
        var stdout = process.StandardOutput.ReadToEndAsync();
        var stderr = process.StandardError.ReadToEndAsync();
        await process.WaitForExitAsync();
        process.ExitCode.Should().Be(0, await stderr);
        using var doc = JsonDocument.Parse(await stdout);
        return doc.RootElement.GetProperty("services").EnumerateObject().ToDictionary(p => p.Name, p => p.Value.Clone());
    }

    private void StartHost(JsonElement service)
    {
        var psi = new ProcessStartInfo(Environment.GetEnvironmentVariable("DOTNET_HOST_PATH") is { Length: > 0 } path && File.Exists(path) ? path : "dotnet")
        {
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            WorkingDirectory = _hostFolder,
        };
        psi.ArgumentList.Add(Path.Combine(_hostFolder, "Xrmd.Host.dll"));
        foreach (var key in psi.Environment.Keys.ToList())
            if (key.StartsWith("ASPNETCORE_", StringComparison.Ordinal) || key.StartsWith("DOTNET_", StringComparison.Ordinal) || key.Contains("__"))
                psi.Environment.Remove(key);
        foreach (var variable in service.GetProperty("environment").EnumerateObject())
            psi.Environment[variable.Name] = variable.Value.GetString()!.Replace("$$", "$");
        psi.Environment["ConnectionStrings__Org"] = new SqlConnectionStringBuilder(psi.Environment["ConnectionStrings__Org"])
        {
            DataSource = new SqlConnectionStringBuilder(_sql!.GetConnectionString()).DataSource,
        }.ConnectionString;
        psi.Environment["ASPNETCORE_URLS"] = $"http://127.0.0.1:{Port}";
        psi.Environment["Files__FileSystem__Root"] = Path.Combine(_root, "files");
        psi.Environment[SdkFolder.DirectoryVariable] = _sdk; // what the image's bind mount of <installation>/sdk provides

        _host = Process.Start(psi)!;
        DataReceivedEventHandler append = (_, e) =>
        {
            if (e.Data is null) return;
            lock (_hostOutput) _hostOutput.AppendLine(e.Data);
            try { output.WriteLine(e.Data); } catch (InvalidOperationException) { }
        };
        _host.OutputDataReceived += append;
        _host.ErrorDataReceived += append;
        _host.BeginOutputReadLine();
        _host.BeginErrorReadLine();
    }

    private async Task WaitHealthyAsync()
    {
        var deadline = DateTime.UtcNow + TimeSpan.FromMinutes(4);
        while (DateTime.UtcNow < deadline)
        {
            if (_host!.HasExited) throw new Xunit.Sdk.XunitException($"xrmd-acme exited with {_host.ExitCode}:\n{HostOutput}");
            try
            {
                if ((await _http.GetAsync($"http://localhost:{Port}/healthz")).StatusCode == HttpStatusCode.OK) return;
            }
            catch (HttpRequestException) { }
            await Task.Delay(500);
        }
        throw new Xunit.Sdk.XunitException($"xrmd-acme did not answer /healthz:\n{HostOutput}");
    }

    /// <summary><c>server init</c> runs no docker command; any call is a test failure.</summary>
    private sealed class NoDocker : IProcessRunner
    {
        public Task<ProcessResult> RunAsync(ProcessSpec spec, CancellationToken cancellationToken = default) =>
            throw new InvalidOperationException("server init must not run " + spec.FileName);
    }
}
